package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import org.kanger.*;
import org.kanger.exception.*;
import org.kanger.enums.StorageLifecycleErrorCode;

/** Existing explicit writer boundaries: private initialized pins, native local failures, TRUST refusal. */
final class ContextNativeWriterCompatibilityMatrix {
    static int checks;static final int WORK=64000000;
    static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
    static ContextNativeCandidateInspection.Limits limits(){return ContextNativeWriterMatrix.limits(WORK);}
    static boolean write(ContextNativeCandidateLeaseMatrix.Fixture f,String s)throws Exception{return f.db.writeNativeProductionCandidate(f.mind,s,limits(),WORK,WORK,1000000,false);}
    static ContextProductionInventory foreign(ContextNativeCandidateLeaseMatrix.Fixture f,UUID id)throws Exception{for(ContextConnection c:f.db.dmzTopology())if(c.getTarget().getContextId().equals(id))return ContextProductionInventory.inspect(c.layer(),id,c.getTarget().getRevision(),false,c.getInitialization(),1000);throw new AssertionError("member missing");}
    static void initialized()throws Exception{
        Path dir=Files.createTempDirectory("native-writer-initialized-");System.setProperty("user.home",dir.toString());RevisionRef a=ContextNativeCandidateLeaseMatrix.create(dir,"A","!left(1); !p(1);");ContextNativeCandidateLeaseMatrix.create(dir,"B","!right(1); !~p(1);");
        for(boolean reverse:new boolean[]{false,true}){String name="Initialized"+reverse;long revision;
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.mind.compile("!anchor(1);",null,false),"physical initialized baseline");if(reverse)f.db.connectContext("B");f.db.connectContext("A");f.db.switchContextRevision("A",a.getRevision());if(!reverse)f.db.connectContext("B");f.db.saveConnections(f.mind);long before=f.db.getRevision();Set<String> original=ContextNativeCommitGuardMatrix.primary(f);String raw=foreign(f,a.getContextId()).fingerprint;
                f.db.applyConnectionCommand(f.mind,"A","-left(1);");f.db.applyConnectionCommand(f.mind,"A","!left(2);");ContextProductionInventory init=foreign(f,a.getContextId());require(init.revision==a.getRevision()&&!init.fingerprint.equals(raw)&&init.initialization.size()==2,"actual same-pin private view has separate fingerprint and complete commands");require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"private initialization not physical parent publication");
                ContextNativeCandidateInspection.Result historical=f.db.inspectNativeProductionCandidate(f.mind,ContextNativeWriterMatrix.MASKED,limits());require(historical.status==ContextNativeCandidateInspection.Status.STABLE_SUPPLIED,"fresh private initialized candidate diagnostic is scoped stable");
                try(ContextNativeCandidateLeaseMatrix.Fixture other=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"A")){require(other.mind.query("!headOnly("+(reverse?8:7)+");",null,false),"foreign physical head advances independently");require(other.db.getRevision()>a.getRevision(),"later physical foreign revision fixture");}
                require(foreign(f,a.getContextId()).revision==a.getRevision()&&foreign(f,a.getContextId()).fingerprint.equals(init.fingerprint),"existing initialized cut remains exact pinned revision after head advance");
                f.db.applyConnectionCommand(f.mind,"A","!left(1);");ContextNativeCommitException conflict=null;try{write(f,ContextNativeWriterMatrix.MASKED);}catch(ContextNativeCommitException e){conflict=e;}require(conflict!=null&&conflict.getErrorCode()==StorageLifecycleErrorCode.STORAGE_CONTEXT_CONFLICT&&conflict.getNativeEvidence()!=null,"historical scoped success cannot bypass fresh changed initialization collision");ContextProductionInventory changed=foreign(f,a.getContextId());for(ContextNativeBranchInspection.Opposition o:conflict.getNativeEvidence().getOppositions())for(org.kanger.ContextProductionCapture.Source s:o.sources)if(s.context.equals(a.getContextId()))require(s.revision==a.getRevision()&&s.view.equals("inventory:"+changed.fingerprint),"rejection preserves exact private view Source, not target head/raw inventory");conflict.getNativeEvidence().check(WORK,1);require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).equals(original),"changed-view conflict is atomic and source originals remain local");
                f.db.applyConnectionCommand(f.mind,"A","-left(1);");ContextProductionInventory beforeSave=foreign(f,a.getContextId());long preSave=f.db.getRevision();f.db.saveConnections(f.mind);require(f.db.getRevision()>preSave,"initialization-only save with SAME target pins must publish configuration");ContextProductionInventory afterSave=foreign(f,a.getContextId());require(afterSave.primary.stream().map(r->r.origin).collect(java.util.stream.Collectors.toSet()).equals(beforeSave.primary.stream().map(r->r.origin).collect(java.util.stream.Collectors.toSet()))&&afterSave.initialization.equals(beforeSave.initialization)&&afterSave.revision==beforeSave.revision,"save preserves actual initialized view, never silently reloads original target");require(f.db.inspectNativeProductionCandidate(f.mind,ContextNativeWriterMatrix.MASKED,limits()).status==ContextNativeCandidateInspection.Status.STABLE_SUPPLIED,"reconstructed initialized native view remains semantically stable after save");long saved=f.db.getRevision();f.db.saveConnections(f.mind);require(f.db.getRevision()==saved,"unchanged complete configuration save stays idempotent");long preWrite=f.db.getRevision();require(write(f,ContextNativeWriterMatrix.MASKED),"fresh native+full-family+legacy gates permit privately initialized safe rule");require(f.db.getRevision()>preWrite&&ContextNativeCommitGuardMatrix.primary(f).size()==2&&ContextNativeCommitGuardMatrix.primary(f).contains(ContextNativeWriterMatrix.MASKED),"only original rule plus anchor published");require(foreign(f,a.getContextId()).revision==a.getRevision()&&foreign(f,a.getContextId()).initialization.size()==4,"publication retains original exact pin and full private initialization sequence");revision=f.db.getRevision();
            }
            try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,name)){require(f.db.getRevision()>=revision&&ContextNativeCommitGuardMatrix.primary(f).size()==2,"private initialized publication durable");ContextProductionInventory view=foreign(f,a.getContextId());require(view.revision==a.getRevision()&&view.initialization.size()==4&&view.primary.stream().noneMatch(r->r.origin.contains("headOnly")),"reopen reconstructs persisted initialization from pinned target, never advanced head");}
        }
        System.out.println("NATIVE_WRITER_INITIALIZED orders=2 privateViews=true exactPinsAfterHeadAdvance=true historicalSuccessNotAuthority=true changedViewRefutation=true actualPublicationReopen=true");
    }
    interface Attempt{void run()throws Exception;}
    static void reject(Attempt a,String why)throws Exception{boolean rejected=false;try{a.run();}catch(Exception expected){rejected=true;}require(rejected,why);}
    static void legacy()throws Exception{
        Path dir=Files.createTempDirectory("native-writer-legacy-");System.setProperty("user.home",dir.toString());ContextNativeCandidateLeaseMatrix.create(dir,"TR","!@u p(u)->q(u);");ContextNativeCandidateLeaseMatrix.create(dir,"TF","!p(1);");
        for(boolean reverse:new boolean[]{false,true})try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"Trust"+reverse)){require(f.mind.compile("!anchor(1);",null,false),"trusted boundary parent");f.db.connectContext(reverse?"TF":"TR");f.db.connectContext(reverse?"TR":"TF");f.db.saveConnections(f.mind);long untrusted=f.db.getRevision();f.db.connectContext("TR","own");f.db.connectContext("TF","own");f.db.saveConnections(f.mind);require(f.db.getRevision()>untrusted&&f.db.dmzTopology().stream().allMatch(c->"own".equals(c.getTrustGroup())),"TRUST-only save with unchanged pins publishes complete group configuration");long revision=f.db.getRevision();Set<String> before=ContextNativeCommitGuardMatrix.primary(f);boolean unsupported=false;try{write(f,"!@u q(u)->r(u);");}catch(IllegalStateException e){unsupported=e.getMessage().contains("TRUST effective view requires separate production snapshot support");}require(unsupported,"exact existing settled-root TRUST boundary refuses before selection, never flattens group");require(f.db.getRevision()==revision&&ContextNativeCommitGuardMatrix.primary(f).equals(before),"unsupported TRUST writer has no physical effect");f.db.disconnectContext("TR");f.db.disconnectContext("TF");require(write(f,"!afterTrust(2);"),"TRUST preflight failure leaves no installed attempt");}
        try(ContextNativeCandidateLeaseMatrix.Fixture f=new ContextNativeCandidateLeaseMatrix.Fixture(dir,"Local")){require(f.mind.compile("!anchor(1);",null,false),"local native conflict fixture");long before=f.db.getRevision();Boolean ordinary=f.mind.query("!~anchor(1);",null,false);boolean selected=write(f,"!~anchor(1);");System.out.println("NATIVE_LOCAL_ACCEPTANCE ordinary="+ordinary+" selected="+selected);require(!Boolean.TRUE.equals(ordinary)&&!selected,"ordinary nonacceptance maps to selected false acceptance");require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).size()==1,"native local refusal publishes nothing");reject(()->write(f,"!@;"),"native syntax failure propagates");require(f.db.getRevision()==before&&ContextNativeCommitGuardMatrix.primary(f).size()==1,"native syntax failure preserves physical state");require(write(f,"!afterFailure(2);"),"false acceptance and syntax exception both clean up attempt selection");require(f.mind.query("!ordinaryAfter(3);",null,false),"ordinary follow-up remains unchanged after selected failure recovery");require(ContextNativeCommitGuardMatrix.primary(f).size()==3,"only successful original assertions retained");}
        System.out.println("NATIVE_WRITER_LEGACY trustOrders=2 trustFailsClosed=true noFlattening=true nativeFalseAcceptance=true syntaxFailure=true selectionCleanup=true ordinaryFollowup=true");
    }
}
